<script setup lang="ts">import{onMounted,ref}from"vue";import{get,post}from"../api";const tasks=ref<any[]>([]),title=ref(""),status=ref("");async function load(){tasks.value=await get(`/tasks${status.value?`?status=${status.value}`:""}`)}async function add(){await post("/tasks",{title:title.value,priority:"中"});title.value="";load()}onMounted(load);</script><template><h1>任务管理</h1><div class="row"><input v-model="title" placeholder="任务标题"><button @click="add">添加任务</button><select v-model="status" @change="load"><option value="">全部状态</option><option>待办</option><option>进行中</option><option>已完成</option></select></div><div class="panel" v-for="task in tasks" :key="task.id">{{task.title}} · {{task.status}} · {{task.priority}}</div></template>
